# Autotune configs span num_stages=1,2,3,4; vectorized hints added
@triton.autotune(
    configs=[
        triton.Config({'XBLOCK': 1024, 'YBLOCK': 1}, num_warps=4, num_stages=1),
        # ... num_stages=1 subset ...
        triton.Config({'XBLOCK': 1024, 'YBLOCK': 1}, num_warps=4, num_stages=2),
        triton.Config({'XBLOCK': 512,  'YBLOCK': 2}, num_warps=4, num_stages=2),
        triton.Config({'XBLOCK': 1024, 'YBLOCK': 1}, num_warps=4, num_stages=3),
        triton.Config({'XBLOCK': 512,  'YBLOCK': 1}, num_warps=8, num_stages=4),
        # ... more num_stages=3,4 configs ...
    ],
    key=['ynumel', 'xnumel'],
)
@triton.jit
def kernel(...):
    xoffset = tl.program_id(0) * XBLOCK
    xindex = xoffset + tl.max_contiguous(
        tl.multiple_of(tl.arange(0, XBLOCK), XBLOCK), XBLOCK
    )[None, :]  # signals stride-1 alignment for 128-bit vectorized loads
    tmp0 = tl.load(in_ptr + (x2 + stride*y3), mask)

